const fade  = 1 - clamp(r * 1.8, 0, 1);
return hsv(0.58, 0.9, ring * fade);`},{id:"lava",name:"Lava Lamp",desc:"Slow organic blobs rising and merging in warm colors",preview:"radial-gradient(ellipse at 30% 70%,#ff4400 0%,#cc0000 30%,#220000 100%)",code:`// @param speed float 0.2 0.05 1.0
