return hsv(h, 1, v);`},{id:"ocean",name:"Ocean Wave",desc:"Rolling blue-teal waves with white-foam highlights",preview:"linear-gradient(180deg,#ffffff 0%,#7aecff 20%,#0077b6 60%,#03045e 100%)",code:`// @param speed float 0.5 0.1 2.0
